WITH flattened_attrs AS (SELECT id, items, ship_to, attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, FORALL(items, item -> item.qty <= 5) AS all_small_qty, COALESCE(attributes['device'], 'direct') AS device_or_default FROM carts) SELECT CASE WHEN weight_kg >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END AS weight_kg_tier, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(weight_kg), 2) AS avg_weight_kg, COUNT(*) AS num_rows, AVG(weight_kg) AS avg_weight_kg_2 FROM flattened_attrs GROUP BY CASE WHEN weight_kg >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_weight_kg_2 NULLS FIRST;
